set text = v.txt
from (values
  ('056de175-bc27-45bf-9030-81198d845549'::uuid, 'pl', 'Psa z hodowli nie dostaniesz bez rozmowy, dziecko — bez niczego'),
  ('056de175-bc27-45bf-9030-81198d845549'::uuid, 'en', 'A breeder vets you before selling a puppy; a child takes nothing'),
  ('5bdee1d5-b272-4769-9398-7c67d354436c'::uuid, 'pl', 'Algorytm się pomyli — i kogo wtedy pozwiesz?'),
  ('5bdee1d5-b272-4769-9398-7c67d354436c'::uuid, 'en', 'When the algorithm gets it wrong, who do you sue?'),
  ('8c6fbe9f-80f1-41ff-af30-d40f4b931616'::uuid, 'pl', 'Prawo do śmierci łatwo staje się presją, by nie być ciężarem'),
  ('8c6fbe9f-80f1-41ff-af30-d40f4b931616'::uuid, 'en', 'The right to die soon becomes pressure not to be a burden'),
  ('d81b360a-f1d1-4da3-bb6c-19e5f4f84f76'::uuid, 'pl', 'Ilu mistrzów dziękuje trenerowi, który zawsze odpuszczał?'),
  ('d81b360a-f1d1-4da3-bb6c-19e5f4f84f76'::uuid, 'en', 'How many champions thank the coach who always went easy?'),
  ('6da7452b-c88f-4353-a169-d0f73d1887ad'::uuid, 'pl', 'Obroniłbyś łagodny wyrok, patrząc w oczy rodzinie ofiary?'),
  ('6da7452b-c88f-4353-a169-d0f73d1887ad'::uuid, 'en', 'Could you defend a soft sentence to the victim''s family?'),
  ('b6163e77-1c1f-48ca-9da8-93d7606fd794'::uuid, 'pl', 'Zysk wydasz w dekadę, wyciętego lasu nie odkupisz nigdy'),
  ('b6163e77-1c1f-48ca-9da8-93d7606fd794'::uuid, 'en', 'The profit is gone in a decade; the forest never comes back'),
  ('4a6dfa82-ec4c-4489-8d70-1507d6c03029'::uuid, 'pl', 'Planujesz rozstanie, zanim jeszcze padnie przysięga?'),
  ('4a6dfa82-ec4c-4489-8d70-1507d6c03029'::uuid, 'en', 'Planning the break-up before the vows are even spoken?'),
  ('1b66925a-2aa8-4090-aaf6-c4cc32a6d75b'::uuid, 'pl', 'Z więzienia wyjdzie równie głodny — co naprawił ten wyrok?'),
  ('1b66925a-2aa8-4090-aaf6-c4cc32a6d75b'::uuid, 'en', 'He leaves prison just as hungry — what did the sentence fix?'),
  ('f7fb4202-5e23-4c39-a052-4d9a0abfc3b7'::uuid, 'pl', 'Pijesz czystą wodę, bo ktoś sto lat temu odmówił sobie zysku'),
  ('f7fb4202-5e23-4c39-a052-4d9a0abfc3b7'::uuid, 'en', 'You drink clean water because someone once gave up their profit'),
  ('26877062-26dc-4397-a9bf-4197812a41d6'::uuid, 'pl', 'Jeden głupi wpis z liceum ma cię ścigać do końca życia?'),
  ('26877062-26dc-4397-a9bf-4197812a41d6'::uuid, 'en', 'Should one dumb post from school chase you for life?'),
  ('b5756fa7-620a-46ae-a7b2-766bc65df29c'::uuid, 'pl', 'Wasi dziadkowie czekali na siebie latami — bez wideorozmów'),
  ('b5756fa7-620a-46ae-a7b2-766bc65df29c'::uuid, 'en', 'Your grandparents waited years for each other — no video calls'),
  ('7e2ff20c-b410-423a-b4c4-f31e23039585'::uuid, 'pl', 'Pokolenie wychowane na tabletach nie wygląda na szczęśliwsze'),
  ('7e2ff20c-b410-423a-b4c4-f31e23039585'::uuid, 'en', 'The tablet-raised generation does not look any happier'),
  ('edd5df8c-4687-468d-9928-b87f5a7d27d4'::uuid, 'pl', 'Osoba, która zna cię najlepiej, ma zniknąć, bo tak wypada?'),
  ('edd5df8c-4687-468d-9928-b87f5a7d27d4'::uuid, 'en', 'The person who knows you best must vanish — says who?'),
  ('4fff8f96-29ff-4a9a-bfee-22af0fc944bb'::uuid, 'pl', 'I tak kupiłbyś bilet na ten film — i dobrze o tym wiesz'),
  ('4fff8f96-29ff-4a9a-bfee-22af0fc944bb'::uuid, 'en', 'You would still buy a ticket to that film — and you know it'),
  ('7e8ab3b2-8d82-4dd9-ac0d-877469dc16a8'::uuid, 'pl', 'Bez powtórki w domu lekcja wyparuje do rana'),
  ('7e8ab3b2-8d82-4dd9-ac0d-877469dc16a8'::uuid, 'en', 'Without practice at home, the lesson is gone by morning'),
  ('65d9e9cd-8257-4bbd-bd8e-83d50684466e'::uuid, 'pl', 'Łatwo mówić „próżność", gdy samemu nie chce się wstać z kanapy'),
  ('65d9e9cd-8257-4bbd-bd8e-83d50684466e'::uuid, 'en', 'Easy to call it vanity when you will not get off the sofa'),
  ('f6c00ad7-cf34-45fc-9991-70bf66691b61'::uuid, 'pl', 'Odrzuci cię wzorzec z cudzych danych i nikt nie powie dlaczego'),
  ('f6c00ad7-cf34-45fc-9991-70bf66691b61'::uuid, 'en', 'A pattern in someone else''s data rejects you — no one says why'),
  ('61ef55bd-ce08-4f7e-9453-7e6b474dc3b5'::uuid, 'pl', 'Wzruszyła cię maszyna — nie chciałbyś o tym wiedzieć?'),
  ('61ef55bd-ce08-4f7e-9453-7e6b474dc3b5'::uuid, 'en', 'A machine moved you to tears — wouldn''t you want to know?'),
  ('1b74971c-3a4c-4c56-ad09-c988a83506c9'::uuid, 'pl', 'Z aplikacją projektowaną na uzależnienie dziecko samo nie wygra'),
  ('1b74971c-3a4c-4c56-ad09-c988a83506c9'::uuid, 'en', 'A child cannot out-will an app designed to be addictive'),
  ('bc949ba3-1e44-49d3-a960-1818919e6b8c'::uuid, 'pl', 'Cała prawda naraz to dla pięciolatka ciężar, nie szczerość'),
  ('bc949ba3-1e44-49d3-a960-1818919e6b8c'::uuid, 'en', 'The whole truth at once is a burden for a five-year-old'),
  ('7293fcf0-75e8-4930-9a23-831e5c2a5a2f'::uuid, 'pl', 'Wyłączność po jednej kawie to obietnica, w którą nie wierzysz'),
  ('7293fcf0-75e8-4930-9a23-831e5c2a5a2f'::uuid, 'en', 'Exclusive after one coffee — a promise you don''t believe'),
  ('6b321d66-02ca-46c0-83f7-cb21f9df4d15'::uuid, 'pl', 'Paczki z kartami piłkarzy kupowało się od zawsze — też hazard?'),
  ('6b321d66-02ca-46c0-83f7-cb21f9df4d15'::uuid, 'en', 'Kids always bought football card packs — was that gambling too?'),
  ('90e6f44c-f905-461f-9c10-c228b300b974'::uuid, 'pl', 'Pytanie pięciolatka to nie zaproszenie na wykład z biologii'),
  ('90e6f44c-f905-461f-9c10-c228b300b974'::uuid, 'en', 'A five-year-old''s question is not a request for a biology lecture'),
  ('0054eac9-9f56-4193-8333-f2c2c2509613'::uuid, 'pl', 'Umierając, oddałbyś wszystko za rok więcej — tu masz dwadzieścia'),
  ('0054eac9-9f56-4193-8333-f2c2c2509613'::uuid, 'en', 'On your deathbed you''d give anything for a year — here are twenty'),
  ('b08e4500-d2e3-44b0-8788-7c3dc3b88baa'::uuid, 'pl', 'Z lekcji, których nienawidziłeś, nie pamiętasz dziś niczego'),
  ('b08e4500-d2e3-44b0-8788-7c3dc3b88baa'::uuid, 'en', 'You remember nothing from the lessons you were forced through'),
  ('e6aaaa6a-52d5-424d-b6da-a421edc15135'::uuid, 'pl', 'Odmawiasz teraz — na łożu śmierci wziąłbyś bez wahania'),
  ('e6aaaa6a-52d5-424d-b6da-a421edc15135'::uuid, 'en', 'You refuse today; on your deathbed you''d take it in a heartbeat'),
  ('a4aee45e-97f0-4982-b34c-c4f1f903d4dd'::uuid, 'pl', 'Komplement na imprezie to już powód do rozstania?'),
  ('a4aee45e-97f0-4982-b34c-c4f1f903d4dd'::uuid, 'en', 'A compliment at a party — grounds for a break-up?'),
  ('8ae9b0dd-db42-4175-a589-d895d4ca8a27'::uuid, 'pl', 'Pięć minut w internecie oszczędza czasem bardzo złą godzinę'),
  ('8ae9b0dd-db42-4175-a589-d895d4ca8a27'::uuid, 'en', 'Five minutes online can spare you one very bad hour'),
  ('3ad91cde-f80b-429f-b842-60f3b71bf188'::uuid, 'pl', '„Chłopaki nie płaczą" — to chcesz powtarzać synowi?'),
  ('3ad91cde-f80b-429f-b842-60f3b71bf188'::uuid, 'en', 'Boys don''t cry — is that what you''ll keep telling your son?'),
  ('e0b68105-0580-4bfe-85d4-d1a22f99d7b9'::uuid, 'pl', 'Trzeci raz w tygodniu zamawiasz i nazywasz to oszczędnością czasu?'),
  ('e0b68105-0580-4bfe-85d4-d1a22f99d7b9'::uuid, 'en', 'Third takeaway this week — still calling it saving time?'),
  ('7504a059-4c54-4c2b-a8e2-5471d5e3fbd3'::uuid, 'pl', 'Rano nie będziesz wiedzieć, czy chodziło o ciebie, czy o ciało'),
  ('7504a059-4c54-4c2b-a8e2-5471d5e3fbd3'::uuid, 'en', 'By morning you won''t know if it was you or just the body'),
  ('98e9a261-e144-481f-be83-6910d115840a'::uuid, 'pl', 'Auto ma przejechać trójkę na pasach, żeby ocalić ciebie?'),
  ('98e9a261-e144-481f-be83-6910d115840a'::uuid, 'en', 'Should the car mow down three on a crossing to save you?'),
  ('2c586557-d4f6-40c4-83b9-a94b411fa129'::uuid, 'pl', 'Drugie dziecko kochasz mniej? Serce się nie dzieli, tylko rośnie'),
  ('2c586557-d4f6-40c4-83b9-a94b411fa129'::uuid, 'en', 'Love your second child less? Hearts grow, they don''t split'),
  ('9bd686c2-881d-4ca5-8b8f-605606195513'::uuid, 'pl', 'Zakochujesz się w człowieku czy w jego karcie wyborczej?'),
  ('9bd686c2-881d-4ca5-8b8f-605606195513'::uuid, 'en', 'Do you fall for the person or for their ballot paper?'),
  ('51ffc8f0-7694-44d1-87dd-2178ccdf5de4'::uuid, 'pl', 'Całe życie w tym samym bloku — to cię nie przeraża bardziej?'),
  ('51ffc8f0-7694-44d1-87dd-2178ccdf5de4'::uuid, 'en', 'A whole life in the same flat — isn''t that the scarier end?'),
  ('c33d0df1-0f7b-4164-9aaf-b44e7640858e'::uuid, 'pl', 'Nie głosując, oddajesz decyzję tym, którym się chciało'),
  ('c33d0df1-0f7b-4164-9aaf-b44e7640858e'::uuid, 'en', 'By staying home you hand the choice to those who showed up'),
  ('164128b7-868f-4d49-b0c7-3c6999d6551a'::uuid, 'pl', 'Obcy zrzucają się na jego wakacje, ty na swoje pracujesz'),
  ('164128b7-868f-4d49-b0c7-3c6999d6551a'::uuid, 'en', 'Strangers fund his holiday; you work for yours'),
  ('15bb40d7-b784-40cf-8329-b718d45fd64e'::uuid, 'pl', 'Pomoc z banku to rozsądek, a od mamy to wstyd?'),
  ('15bb40d7-b784-40cf-8329-b718d45fd64e'::uuid, 'en', 'Help from a bank is smart, but from your mum it''s shame?'),
  ('f43e9c12-8a96-4926-9752-1a53e65b6288'::uuid, 'pl', 'Choroba wykryta rok wcześniej to często dekady życia więcej'),
  ('f43e9c12-8a96-4926-9752-1a53e65b6288'::uuid, 'en', 'Caught a year earlier, an illness can mean decades more'),
  ('f14c284d-2679-4793-8171-953486de5356'::uuid, 'pl', 'Pół roku pracy na siłowni i nie wolno powiedzieć miłego słowa?'),
  ('f14c284d-2679-4793-8171-953486de5356'::uuid, 'en', 'Six months of hard work and no one''s allowed a kind word?'),
  ('ab47a11b-8f6d-474a-a31b-9fb83273d1b5'::uuid, 'pl', 'Koncern truje, bo ty kupujesz — portfelem głosujesz codziennie'),
  ('ab47a11b-8f6d-474a-a31b-9fb83273d1b5'::uuid, 'en', 'Industry pollutes because you buy — your wallet votes daily'),
  ('5ab9c918-9ced-4fa7-a1e5-ecc9ef8b6dd0'::uuid, 'pl', 'Wymień trzy remaki lepsze od oryginału — czekam'),
  ('5ab9c918-9ced-4fa7-a1e5-ecc9ef8b6dd0'::uuid, 'en', 'Name three remakes better than the original — go on'),
  ('b941dbc8-8c68-451d-ae6a-0311517f9b03'::uuid, 'pl', 'Dostałeś coś od serca i nazywasz to ciężarem?'),
  ('b941dbc8-8c68-451d-ae6a-0311517f9b03'::uuid, 'en', 'Someone gave from the heart and you call it a burden?')
) as v(sid, locale, txt)
where st.smaczek_id = v.sid and st.locale = v.locale;

commit;
